import{_ as s,o as a,c as i,a4 as t}from"./chunks/framework.BE47AOxC.js";const f=JSON.parse('{"title":"ADR-0068 — Polices à nom réservé servies sans modification, affichage adaptatif vérifié sans comparaison au pixel","description":"Extrait de docs/adr/0068-polices-a-nom-reserve-et-verification-adaptative.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0068 — Polices à nom réservé servies sans modification, affichage adaptatif vérifié sans comparaison au pixel","description":"Extrait de docs/adr/0068-polices-a-nom-reserve-et-verification-adaptative.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0068-polices-a-nom-reserve-et-verification-adaptative.md","filePath":"developpeurs/adr/0068-polices-a-nom-reserve-et-verification-adaptative.md"}'),r={name:"developpeurs/adr/0068-polices-a-nom-reserve-et-verification-adaptative.md"};function o(n,e,c,l,d,u){return a(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="adr-0068--polices-à-nom-réservé-servies-sans-modification-affichage-adaptatif-vérifié-sans-comparaison-au-pixel" tabindex="-1">ADR-0068 — Polices à nom réservé servies sans modification, affichage adaptatif vérifié sans comparaison au pixel <a class="header-anchor" href="#adr-0068--polices-à-nom-réservé-servies-sans-modification-affichage-adaptatif-vérifié-sans-comparaison-au-pixel" aria-label="Permalink to &quot;ADR-0068 — Polices à nom réservé servies sans modification, affichage adaptatif vérifié sans comparaison au pixel {#adr-0068--polices-à-nom-réservé-servies-sans-modification-affichage-adaptatif-vérifié-sans-comparaison-au-pixel}&quot;">​</a></h1><p><strong>Date :</strong> 8 octobre 2026 <strong>Statut :</strong> Accepté <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> lot 14 (issue #9), réalisation de l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0049-identite-visuelle-du-site-public">ADR-0049</a> ; FAQ officielle de l&#39;OFL, version 1.1-update7, section 2 (<a href="https://openfontlicense.org/ofl-faq/" target="_blank" rel="noreferrer">https://openfontlicense.org/ofl-faq/</a>) <strong>Amende :</strong> <a href="/teuthis-cms-distribution/developpeurs/adr/0049-identite-visuelle-du-site-public">ADR-0049</a>, décision n° 4 (« deux ou trois graisses par police, en woff2, avec les caractères du latin étendu ») et décision n° 5 (« captures d&#39;écran comparées »)</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>Le lot 14 embarque dans le front les quinze polices du registre (<code>apps/api/app/theming/fonts.py</code>) et vérifie l&#39;affichage adaptatif en CI. Deux points de l&#39;ADR-0049 se heurtent à des faits que l&#39;ADR ne pouvait pas connaître.</p><p><strong>Les polices à nom réservé.</strong> Neuf polices du registre déclarent un <em>Reserved Font Name</em> dans leur licence OFL 1.1 ou dans leur table <code>name</code> : Source Sans 3, Source Serif 4, Fira Sans, IBM Plex Sans, IBM Plex Serif, Lora, Merriweather, Libre Baskerville et Playfair Display. Selon la FAQ officielle de l&#39;OFL, une version WOFF peut garder le nom de la police « only if the original font data remains unchanged except for WOFF compression ». Réduire le fichier au latin étendu en fait une version modifiée, qui ne peut plus porter le nom réservé sans l&#39;accord de ses auteurs. Or le registre et le back-office affichent ce nom.</p><p><strong>Les captures comparées.</strong> Une comparaison au pixel avec une référence stockée dans le dépôt échoue au moindre changement de rendu des polices ou du navigateur. Il faut alors régénérer la référence à chaque évolution visuelle voulue, et l&#39;échec n&#39;indique pas de défaut d&#39;accessibilité.</p><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><p><strong>1. Les polices à nom réservé sont servies sans modification.</strong></p><ul><li>Pour ces neuf polices, le front sert les fichiers d&#39;origine en woff2, <strong>sans réduction ni retouche</strong> : le woff2 officiel de la fonderie quand ses tables sont identiques au fichier d&#39;origine, sinon une simple compression WOFF2 du fichier statique d&#39;origine, transformation des glyphes désactivée.</li><li><code>apps/front/scripts/fabriquer-polices.py</code> le prouve <strong>table par table</strong> : chaque table du woff2 servi est identique, octet pour octet, à celle du fichier d&#39;origine. Il n&#39;admet que les écarts imposés par le format WOFF2 : <code>checkSumAdjustment</code> et le bit 11 de <code>flags</code> dans <code>head</code>, et l&#39;absence de <code>DSIG</code>. Il échoue si une police à nom réservé est réduite.</li><li>Les six autres polices, sans nom réservé, restent réduites au latin étendu, comme l&#39;ADR-0049 le prévoit.</li><li>Le prix est le poids : de 60 à 150 Ko par fichier pour les polices d&#39;origine, contre 12 à 22 Ko pour les réduites. Un site ne charge que ses deux polices, et <code>font-display: swap</code> affiche le texte sans attendre.</li></ul><p><strong>2. L&#39;affichage adaptatif est vérifié par des contrôles déterministes, sans comparaison au pixel.</strong></p><ul><li>Aux trois largeurs (375, 768 et 1 280 px), pour chaque page de chaque thème, la CI passe axe, puis vérifie qu&#39;il n&#39;y a pas de défilement horizontal à 320 px, ni avec le texte à 200 %, ni avec l&#39;espacement du texte du RGAA (critère 10.12), et que les zones cliquables font au moins 24 px ou respectent l&#39;exception d&#39;espacement (WCAG 2.5.8).</li><li>Les captures de chaque page à chaque largeur sont jointes à la CI en <strong>artefact</strong>, pour être relues ; elles ne sont pas comparées à une référence.</li></ul><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td>Garder les fichiers réduits et renommer les neuf polices</td><td>Le back-office et la documentation ne pourraient plus dire « Source Sans 3 » : le nom affiché deviendrait « Teuthis Sans A ». Le choix de la police perdrait son repère.</td></tr><tr><td>Retirer les neuf polices du registre</td><td>Il ne resterait que six polices, dont une seule à empattement, quand l&#39;ADR-0049 en promet de dix à quinze.</td></tr><tr><td>Demander l&#39;accord de chaque fonderie</td><td>Neuf démarches, sans délai garanti, pour gagner quelques dizaines de kilo-octets.</td></tr><tr><td>Comparer les captures au pixel</td><td>Voir le contexte : des échecs sans rapport avec l&#39;accessibilité, et une référence à régénérer à chaque changement visuel voulu.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>Aucune police n&#39;est servie sous un nom réservé après modification.</li><li>La CI échoue sur des défauts d&#39;accessibilité mesurables, pas sur un écart de rendu.</li></ul><p><strong>Négatives</strong></p><ul><li>Les sites qui emploient une police à nom réservé chargent des fichiers plus lourds : jusqu&#39;à 150 Ko par graisse pour Source Sans 3 et Fira Sans.</li><li>Une régression purement visuelle, sans défaut mesurable, ne fait pas échouer la CI : seule la relecture des captures la voit.</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] Polices à nom réservé servies sans modification, preuve table par table dans <code>apps/front/scripts/fabriquer-polices.py</code> et <code>apps/front/polices.json</code> (<code>mode</code>, <code>tables_identiques</code>, <code>ecarts_admis</code>), testée par <code>apps/front/tests/unitaires/polices.test.ts</code>. <strong>Fait le 08/10/2026</strong> (lot 14, issue #9).</li><li>[x] Contrôles adaptatifs déterministes et captures en artefact : <code>apps/front/tests/a11y/controles.mjs</code>, <code>lancer.mjs</code>, artefact <code>captures-front</code> du job <code>front</code> de <code>.github/workflows/ci.yml</code>. <strong>Fait le 08/10/2026</strong>.</li><li>[ ] Faire valider par un juriste la lecture de la FAQ de l&#39;OFL retenue ici (écarts admis par le format WOFF2, nom réservé déclaré seulement dans la table <code>name</code> de Playfair Display).</li></ul>',20)])])}const m=s(r,[["render",o]]);export{f as __pageData,m as default};
